  const currentRatingArray = Array.from({ length: 5 }, (_, i) => Math.floor(currentRating * (i + 1) / 20));
  const newRatingArray = Array.from({ length: 5 }, (_, i) => Math.floor(newRating * (i + 1) / 20));

